(7273467, 1132315, 175381, '<td valign="top">Simple but very nice. I like your composition</td>', 'Simple but very nice. I like your composition', '2014-10-14 13:48:42.000000', NULL, 1),
(7273470, 1132231, 13077, '<td valign="top">Nice, ominous mood here. Good detail in the moon and well composed. The clouds at the top sort of look like a mask from a masquerade.</td>', 'Nice, ominous mood here. Good detail in the moon and well composed. The clouds at the top sort of look like a mask from a masquerade.', '2014-10-14 14:04:44.000000', NULL, 1),
(7273471, 1132357, 13077, '<td valign="top">I like the composition of this one - good use of lots of dark space and large shapes and patterns, as well as good detail but a little bit of softness which doesn''t really hurt in my opinion.</td>', 'I like the composition of this one - good use of lots of dark space and large shapes and patterns, as well as good detail but a little bit of softness which doesn''t really hurt in my opinion.', '2014-10-14 14:06:23.000000', NULL, 1),
(7273472, 1132330, 13077, '<td valign="top">Nicely done lighting for a shot of a black cat on black, and good/interesting composition as well.</td>', 'Nicely done lighting for a shot of a black cat on black, and good/interesting composition as well.', '2014-10-14 14:08:50.000000', NULL, 1),
(7273475, 1132334, 13077, '<td valign="top">Good environment you''ve created with this one. I like the light, and where the lens focus is vs. where the visual focus is.</td>', 'Good environment you''ve created with this one. I like the light, and where the lens focus is vs. where the visual focus is.', '2014-10-14 14:10:53.000000', NULL, 1),
(7273478, 1132352, 13077, '<td valign="top">Excellent. I see it to be a very strong illustration of sibling rivalry - something I''ll have to deal with in a few months.</td>', 'Excellent. I see it to be a very strong illustration of sibling rivalry - something I''ll have to deal with in a few months.', '2014-10-14 14:17:44.000000', NULL, 1),
