(7275750, 1132321, 68503, '<td valign="top">Nice idea and congrats on the ribbon</td>', 'Nice idea and congrats on the ribbon', '2014-10-21 21:45:25.000000', NULL, 0),
(7275873, 1132358, 112739, '<td valign="top">Patience is the best quality to possess when in the street and you certainly did a top notch job here. This couldn''t be better. AND it was considered to be taken with a Leica! Quite the compliment. Congrats Mark!</td>', 'Patience is the best quality to possess when in the street and you certainly did a top notch job here. This couldn''t be better. AND it was considered to be taken with a Leica! Quite the compliment. Congrats Mark!', '2014-10-21 23:56:59.000000', NULL, 0),
